using System.ComponentModel.DataAnnotations; using System.Reflection;  namespace BulkRequest.Connection;  public enum ConnectionMode {     [Display(Name = "")]     None = 0,     [Display(Name = "Схема")]     Schema = 1,     [Display(Name = "База данных")]     Database = 2,     [Display(Name = "Сервер")]     Server = 4,     [Display(Name = "Группа серверов")]     Bulk = 6 }  public record ConnectionModeItem(     string Name,     ConnectionMode Mode);  public static class ConnectionModeItemCollection {     public static List<ConnectionModeItem> GetConnectionModes()     {         List<ConnectionModeItem> connectionModes = [];          foreach (var mode in Enum.GetValues<ConnectionMode>())         {             string? modeName = typeof(ConnectionMode)                 .GetField(mode.ToString())?                 .GetCustomAttribute<DisplayAttribute>()?.GetName();             ConnectionModeItem newModeItem = new(                 modeName ?? mode.ToString(),                 mode);             connectionModes.Add(newModeItem);         }          return connectionModes;     } }